from pathlib import Path
import datetime,hashlib,json
w=Path('.build/round364');p=w/'traffic-review.json';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert sha(p)=='87c2649459c16bf5c0a59a5d7e3440d16f40db39d52cd7a14198051a117274b3';prior=json.loads(p.read_text());rows=[]
for old in prior['runs']:
 hist={int(k):v for k,v in old['weighted_call_count_by_endpoint_byte_length'].items()};total=sum(hist.values());assert total==old['observed_intern_calls']
 ranges={label:sum(count for length,count in hist.items() if lo<=length<=hi) for label,lo,hi in [('4_to_7',4,7),('8_to_24',8,24),('25_to_28',25,28),('29_to_32',29,32)]};eligible=sum(ranges[k] for k in ['4_to_7','8_to_24','25_to_28']);misses=old['original_direct_cache_short_misses_all_lengths']
 rows.append({'case':old['case'],'actual_observed_calls':total,'eligible_4_to_28_calls':eligible,'eligible_fraction':eligible/total,'weighted_ranges':ranges,'eligible_cache_hit_fraction_bounds_NOT_joint_measurement':{'lower':max(0,eligible-misses)/total,'upper':eligible/total}})
d={'observed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'official_score':False,'scope':'Read-only classification of the already-saved364 weighted call-length dictionary ONLY. No summary or raw-input reread, program/profile/model/compiler/benchmark/generator/oracle/image/board run.','prior_traffic_sha256':sha(p),'runs':rows,'nominal_cache_payload_bytes':{'old_per_slot':16,'new_per_slot':32,'slots_per_worker':4096,'old_per_worker':65536,'new_per_worker':131072,'increment_per_worker':65536,'increment_at_12_workers':786432},'memory_limit':'Exact allocated slot-array payload arithmetic, not measured process peak/RSS/chargedM. Standard over-aligned allocator behavior, page touching, lifetimes and possible arena reuse/unmapping can change the peak.','eligibility_limit':'These are actual per-call byte-length counts, not unique-name weights. Exact hit-by-length counters are absent; only loose valid bounds are available. No time/K improvement inferred.','status':'Read-only extension; not an implemented or tested candidate.'};out=w/'coverage32-review.json';assert not out.exists();out.write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'path':str(out),'sha256':sha(out),'traffic':[{**row,'eligible_pct':100*row['eligible_fraction']} for row in rows]},indent=2))
